import bcrypt from 'bcryptjs'
import { prisma } from '../lib/prisma.js'
import { ApiError } from '../utils/ApiError.js'
const PAPEIS=new Set(['ADMINISTRADOR','GERENTE','COZINHA','ATENDIMENTO'])
const select={id:true,nome:true,email:true,papel:true,ativo:true,podeCriarUsuarios:true,criadoEm:true}
export async function listar(req,res){res.json(await prisma.usuario.findMany({where:{tipo:'EQUIPE',estabelecimentoId:req.estabelecimentoId},select,orderBy:{nome:'asc'}}))}
function validarCriacaoPermissao(req,pode){ if (pode && (req.usuario?.papel !== 'ADMINISTRADOR' || !req.usuario?.podeCriarUsuarios)) throw new ApiError(403,'Apenas um administrador autorizado pode conceder a permissão de criar usuários.') }
export async function criar(req,res){const {nome,email,papel,senha,podeCriarUsuarios=false}=req.body;if(!nome?.trim()||!email?.trim()||!papel||!senha)throw new ApiError(400,'Informe nome, email, papel e senha.');if(!PAPEIS.has(papel))throw new ApiError(400,'Papel de usuário inválido.');if(String(senha).length<6)throw new ApiError(400,'A senha deve ter pelo menos 6 caracteres.');validarCriacaoPermissao(req,Boolean(podeCriarUsuarios));const senhaHash=await bcrypt.hash(senha,10);res.status(201).json(await prisma.usuario.create({data:{nome:nome.trim(),email:email.trim().toLowerCase(),papel,senhaHash,tipo:'EQUIPE',podeCriarUsuarios:Boolean(podeCriarUsuarios),estabelecimentoId:req.estabelecimentoId},select}))}
export async function atualizar(req,res){const {id}=req.params;const existente=await prisma.usuario.findFirst({where:{id,tipo:'EQUIPE',estabelecimentoId:req.estabelecimentoId}});if(!existente)throw new ApiError(404,'Usuário não encontrado.');const {nome,email,papel,senha,podeCriarUsuarios}=req.body;if(papel!==undefined&&!PAPEIS.has(papel))throw new ApiError(400,'Papel de usuário inválido.');validarCriacaoPermissao(req,podeCriarUsuarios!==undefined?Boolean(podeCriarUsuarios):existente.podeCriarUsuarios);const data={...(nome!==undefined&&{nome:nome.trim()}),...(email!==undefined&&{email:email.trim().toLowerCase()}),...(papel!==undefined&&{papel}),...(podeCriarUsuarios!==undefined&&{podeCriarUsuarios:Boolean(podeCriarUsuarios)})};if(senha)data.senhaHash=await bcrypt.hash(senha,10);res.json(await prisma.usuario.update({where:{id},data,select}))}
export async function alternarAtivo(req,res){const atual=await prisma.usuario.findFirst({where:{id:req.params.id,tipo:'EQUIPE',estabelecimentoId:req.estabelecimentoId},select:{ativo:true}});if(!atual)throw new ApiError(404,'Usuário não encontrado.');res.json(await prisma.usuario.update({where:{id:req.params.id},data:{ativo:!atual.ativo},select}))}
export async function remover(req,res){const existente=await prisma.usuario.findFirst({where:{id:req.params.id,tipo:'EQUIPE',estabelecimentoId:req.estabelecimentoId}});if(!existente)throw new ApiError(404,'Usuário não encontrado.');await prisma.usuario.delete({where:{id:existente.id}});res.status(204).send()}
